(()=>{const root=document.documentElement;const primary=document.querySelector('.theme-toggle');const mainHeader=document.querySelector('body>header');let theme='dark';try{theme=localStorage.getItem('jjta-theme')||'dark'}catch{}mainHeader.appendChild(primary);function apply(value){theme=value;root.dataset.theme=value;const isLight=value==='light';document.querySelectorAll('.theme-toggle').forEach(button=>{button.setAttribute('aria-pressed',String(isLight));button.setAttribute('aria-label',isLight?'Aktifkan dark mode':'Aktifkan light mode');button.title=isLight?'Aktifkan dark mode':'Aktifkan light mode';button.querySelector('.theme-icon').textContent=isLight?'☾':'☀';button.querySelector('.theme-label').textContent=isLight?'Dark mode':'Light mode'});try{localStorage.setItem('jjta-theme',value)}catch{}}document.addEventListener('click',e=>{if(e.target.closest('.theme-toggle'))apply(theme==='dark'?'light':'dark')});function ensureAuthToggle(){const header=document.querySelector('#auth-screen>header');if(!header||header.querySelector('.theme-toggle'))return;const button=primary.cloneNode(true);button.classList.add('auth-theme-toggle');header.appendChild(button);apply(theme)}const auth=document.querySelector('#auth-screen');if(auth)new MutationObserver(ensureAuthToggle).observe(auth,{childList:true});apply(theme)})();
